SET ROLE sandbox_owner;
SET search_path = sandbox, pg_catalog;
ALTER DEFAULT PRIVILEGES IN SCHEMA sandbox REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA sandbox REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
CREATE FUNCTION current_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('app.tenant_id',true),'')::uuid$$;
CREATE FUNCTION current_principal() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('app.principal_id',true),'')::uuid$$;
CREATE FUNCTION deny_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'immutable record' USING ERRCODE='55000'; END$$;
CREATE TABLE tenants(id uuid PRIMARY KEY, code text NOT NULL UNIQUE CHECK(code ~ '^[A-Z][A-Z0-9_]{2,31}$'),region text NOT NULL CHECK(length(region) BETWEEN 1 AND 80),state text NOT NULL CHECK(state IN('applicant','verified','suspended','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role_codes(code text PRIMARY KEY CHECK(length(code)=2));
INSERT INTO role_codes(code) VALUES ('OP'),('OA'),('PM'),('CO'),('DV'),('DC'),('DE'),('AN'),('EV'),('SR'),('PI'),('CS'),('ER'),('BY'),('FN'),('SO'),('SU'),('AU'),('CR'),('SV');
CREATE TABLE people(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,verification_digest text NOT NULL CHECK(verification_digest ~ '^[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,verification_digest));
CREATE TABLE principals(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,person_id uuid,kind text NOT NULL CHECK(kind IN('human','service')),subject_digest text NOT NULL CHECK(subject_digest ~ '^[a-f0-9]{64}$'),enabled boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,subject_digest),FOREIGN KEY(tenant_id,person_id) REFERENCES people(tenant_id,id),CHECK((kind='human' AND person_id IS NOT NULL) OR (kind='service' AND person_id IS NULL)));
CREATE TABLE resource_kinds(kind text PRIMARY KEY);
INSERT INTO resource_kinds(kind) VALUES ('institution'),('programme'),('study'),('site'),('access_request'),('dataset'),('dataset_release'),('import'),('artifact'),('protocol'),('configuration'),('metric'),('observation'),('safety_concern'),('review_snapshot'),('budget'),('export'),('report'),('job'),('support_case'),('membership_invitation'),('data_source'),('schema'),('mapping');
CREATE TABLE resources(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,kind text NOT NULL REFERENCES resource_kinds(kind),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),classification text NOT NULL CHECK(classification IN('internal','confidential','restricted','public_approved')),state text NOT NULL CHECK(state IN('draft','submitted','in_review','returned','approved','rejected','active','suspended','revoked','expired','frozen','issued','published','superseded','withdrawn','queued','running','cancel_requested','cancelled','succeeded','failed','quarantined','closed','disposed','open','verifying','complete','aborted','pending','verified','released','feasibility_review','contracted','protocol_review','approved_for_setup','ready','analysis','independent_review','decision_issued','stopped','remote_unconfirmed','transmitted','acknowledged','processed')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,id,kind),FOREIGN KEY(tenant_id,created_by) REFERENCES principals(tenant_id,id));
CREATE INDEX resources_list ON resources(tenant_id,kind,created_at DESC,id DESC);
CREATE TABLE memberships(tenant_id uuid NOT NULL,id uuid NOT NULL,principal_id uuid NOT NULL,role_code text NOT NULL REFERENCES role_codes(code),state text NOT NULL CHECK(state IN('pending','active','revoked','expired')),valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,granted_by uuid NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,granted_by) REFERENCES principals(tenant_id,id),CHECK(valid_from<valid_until));
CREATE INDEX memberships_lookup ON memberships(tenant_id,principal_id,state,valid_until);
CREATE TABLE membership_scopes(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,resource_id uuid NOT NULL,purpose text NOT NULL CHECK(length(purpose) BETWEEN 1 AND 200),PRIMARY KEY(tenant_id,membership_id,resource_id,purpose),FOREIGN KEY(tenant_id,membership_id) REFERENCES memberships(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE auth_contexts(tenant_id uuid NOT NULL,id uuid NOT NULL,principal_id uuid NOT NULL,membership_id uuid,auth_time timestamptz NOT NULL,assurance text NOT NULL CHECK(assurance IN('applicant','mfa','workload')),expires_at timestamptz NOT NULL,revoked_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES memberships(tenant_id,id),CHECK(auth_time<expires_at));
CREATE TABLE resource_versions(tenant_id uuid NOT NULL,resource_id uuid NOT NULL,version bigint NOT NULL CHECK(version>0),schema_name text NOT NULL CHECK(length(schema_name) BETWEEN 1 AND 80),schema_version text NOT NULL CHECK(schema_version='1.1'),canonical_sha256 text NOT NULL CHECK(canonical_sha256 ~ '^[a-f0-9]{64}$'),snapshot_key text NOT NULL CHECK(length(snapshot_key) BETWEEN 1 AND 500),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,resource_id,version),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES principals(tenant_id,id));
CREATE TABLE programmes(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('programme') STORED,code text NOT NULL CHECK(code ~ '^[A-Z][A-Z0-9_]{2,31}$'),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),description text NOT NULL CHECK(length(description) BETWEEN 1 AND 2000),owner_membership_id uuid NOT NULL,mode text NOT NULL CHECK(mode IN('retrospective_evaluation','synthetic_research')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,owner_membership_id) REFERENCES memberships(tenant_id,id),CHECK(starts_at<ends_at));
CREATE TABLE programme_countries(tenant_id uuid NOT NULL,programme_id uuid NOT NULL,country_code text NOT NULL CHECK(country_code ~ '^[A-Z]{2}$'),PRIMARY KEY(tenant_id,programme_id,country_code),FOREIGN KEY(tenant_id,programme_id) REFERENCES programmes(tenant_id,id));
CREATE TABLE studies(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('study') STORED,programme_id uuid NOT NULL,owner_membership_id uuid NOT NULL,objective text NOT NULL CHECK(length(objective) BETWEEN 1 AND 2000),study_type text NOT NULL CHECK(study_type IN('retrospective','synthetic')),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,programme_id) REFERENCES programmes(tenant_id,id),FOREIGN KEY(tenant_id,owner_membership_id) REFERENCES memberships(tenant_id,id));
CREATE TABLE external_references(tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,remote_tenant_id uuid NOT NULL,remote_object_id uuid NOT NULL,remote_kind text NOT NULL CHECK(remote_kind IN('study','evidence','authority_decision')),remote_version bigint NOT NULL CHECK(remote_version>0),remote_region text NOT NULL,verified_sha256 text NOT NULL CHECK(verified_sha256 ~ '^[a-f0-9]{64}$'),verified_by uuid NOT NULL,valid_until timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,id,remote_kind),FOREIGN KEY(tenant_id,verified_by) REFERENCES principals(tenant_id,id),CHECK(tenant_id<>remote_tenant_id));
CREATE TABLE review_snapshots(tenant_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,resource_version bigint NOT NULL,author_person_id uuid NOT NULL,sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,resource_id,resource_version) REFERENCES resource_versions(tenant_id,resource_id,version),FOREIGN KEY(tenant_id,author_person_id) REFERENCES people(tenant_id,id));
CREATE TABLE review_assignments(tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,role_slot text NOT NULL CHECK(role_slot IN('scientific','custodian','safety','institution','disclosure','rights')),reviewer_person_id uuid NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,snapshot_id,role_slot),UNIQUE(tenant_id,snapshot_id,reviewer_person_id),FOREIGN KEY(tenant_id,snapshot_id) REFERENCES review_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,reviewer_person_id) REFERENCES people(tenant_id,id));
CREATE TABLE review_decisions(tenant_id uuid NOT NULL,id uuid NOT NULL,snapshot_id uuid NOT NULL,role_slot text NOT NULL,signer_principal_id uuid NOT NULL,signer_person_id uuid NOT NULL,auth_context_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('approved','returned','rejected')),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 2000),signed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,snapshot_id,role_slot),UNIQUE(tenant_id,snapshot_id,signer_person_id),FOREIGN KEY(tenant_id,snapshot_id,role_slot) REFERENCES review_assignments(tenant_id,snapshot_id,role_slot),FOREIGN KEY(tenant_id,signer_principal_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,signer_person_id) REFERENCES people(tenant_id,id),FOREIGN KEY(tenant_id,auth_context_id) REFERENCES auth_contexts(tenant_id,id));
CREATE FUNCTION validate_signer() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE author uuid; assigned uuid; bound_person uuid; context_ok boolean;
BEGIN
 SELECT author_person_id INTO author FROM review_snapshots WHERE tenant_id=NEW.tenant_id AND id=NEW.snapshot_id;
 SELECT reviewer_person_id INTO assigned FROM review_assignments WHERE tenant_id=NEW.tenant_id AND snapshot_id=NEW.snapshot_id AND role_slot=NEW.role_slot AND expires_at>now();
 SELECT person_id INTO bound_person FROM principals WHERE tenant_id=NEW.tenant_id AND id=NEW.signer_principal_id AND enabled;
 SELECT true INTO context_ok FROM auth_contexts c JOIN memberships m ON m.tenant_id=c.tenant_id AND m.id=c.membership_id WHERE c.tenant_id=NEW.tenant_id AND c.id=NEW.auth_context_id AND c.principal_id=NEW.signer_principal_id AND c.assurance='mfa' AND c.revoked_at IS NULL AND c.expires_at>now() AND c.auth_time BETWEEN now()-interval '5 minutes' AND now() AND m.principal_id=c.principal_id AND m.state='active' AND m.valid_from<=now() AND m.valid_until>now() AND ((NEW.role_slot='scientific' AND m.role_code='SR') OR (NEW.role_slot='custodian' AND m.role_code='DC') OR (NEW.role_slot='safety' AND m.role_code='CS') OR (NEW.role_slot='institution' AND m.role_code='OA') OR (NEW.role_slot='disclosure' AND m.role_code='SR') OR (NEW.role_slot='rights' AND m.role_code='ER'));
 IF author IS NULL OR author=NEW.signer_person_id OR assigned IS DISTINCT FROM NEW.signer_person_id OR bound_person IS DISTINCT FROM NEW.signer_person_id OR context_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'review authority or independence invalid' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER review_signer BEFORE INSERT ON review_decisions FOR EACH ROW EXECUTE FUNCTION validate_signer();
CREATE TABLE artifacts(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('artifact') STORED,sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),size_bytes bigint NOT NULL CHECK(size_bytes>0),media_type text NOT NULL CHECK(length(media_type) BETWEEN 1 AND 120),storage_key text NOT NULL CHECK(length(storage_key) BETWEEN 1 AND 500),region text NOT NULL,state text NOT NULL CHECK(state IN('quarantined','available','rejected','disposed')),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,storage_key),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind));
CREATE TABLE dataset_releases(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('dataset_release') STORED,artifact_id uuid NOT NULL,manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[a-f0-9]{64}$'),released_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,artifact_id) REFERENCES artifacts(tenant_id,id));
CREATE TABLE access_grants(tenant_id uuid NOT NULL,id uuid NOT NULL,release_id uuid NOT NULL,study_id uuid,external_study_ref uuid,external_kind text GENERATED ALWAYS AS ('study') STORED,purpose text NOT NULL CHECK(length(purpose) BETWEEN 1 AND 200),cohort_digest text NOT NULL CHECK(cohort_digest ~ '^[a-f0-9]{64}$'),region text NOT NULL,valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,revoked_at timestamptz,decision_id uuid NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,release_id) REFERENCES dataset_releases(tenant_id,id),FOREIGN KEY(tenant_id,study_id) REFERENCES studies(tenant_id,id),FOREIGN KEY(tenant_id,external_study_ref,external_kind) REFERENCES external_references(tenant_id,id,remote_kind),FOREIGN KEY(tenant_id,decision_id) REFERENCES review_decisions(tenant_id,id),CHECK(num_nonnulls(study_id,external_study_ref)=1),CHECK(valid_from<valid_until));
CREATE TABLE grant_fields(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,field_code text NOT NULL CHECK(field_code ~ '^[a-z][a-z0-9_]{0,79}$'),PRIMARY KEY(tenant_id,grant_id,field_code),FOREIGN KEY(tenant_id,grant_id) REFERENCES access_grants(tenant_id,id));
CREATE TABLE grant_subjects(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,principal_id uuid NOT NULL,PRIMARY KEY(tenant_id,grant_id,principal_id),FOREIGN KEY(tenant_id,grant_id) REFERENCES access_grants(tenant_id,id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id));
CREATE TABLE imports(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('import') STORED,grant_id uuid NOT NULL,artifact_id uuid,source_count bigint NOT NULL CHECK(source_count>=0),accepted_count bigint NOT NULL DEFAULT 0 CHECK(accepted_count>=0),rejected_count bigint NOT NULL DEFAULT 0 CHECK(rejected_count>=0),quarantined_count bigint NOT NULL DEFAULT 0 CHECK(quarantined_count>=0),finalised_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,grant_id) REFERENCES access_grants(tenant_id,id),FOREIGN KEY(tenant_id,artifact_id) REFERENCES artifacts(tenant_id,id),CHECK(finalised_at IS NULL OR accepted_count+rejected_count+quarantined_count=source_count));
CREATE TABLE uploads(tenant_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,grant_id uuid NOT NULL,owner_id uuid NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','verifying','quarantined','complete','aborted','expired','failed')),file_name text NOT NULL CHECK(length(file_name) BETWEEN 1 AND 120),media_type text NOT NULL CHECK(length(media_type) BETWEEN 1 AND 120),purpose text NOT NULL CHECK(length(purpose) BETWEEN 1 AND 200),created_at timestamptz NOT NULL DEFAULT now(),total_bytes bigint NOT NULL CHECK(total_bytes BETWEEN 1 AND 10737418240),sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),chunk_bytes integer NOT NULL DEFAULT 8388608 CHECK(chunk_bytes=8388608),version bigint NOT NULL DEFAULT 1 CHECK(version>0),expires_at timestamptz NOT NULL,artifact_id uuid,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,grant_id) REFERENCES access_grants(tenant_id,id),FOREIGN KEY(tenant_id,owner_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,artifact_id) REFERENCES artifacts(tenant_id,id));
CREATE TABLE upload_parts(tenant_id uuid NOT NULL,upload_id uuid NOT NULL,part_index integer NOT NULL CHECK(part_index BETWEEN 0 AND 1279),size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 8388608),sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),storage_key text NOT NULL,acknowledged_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,upload_id,part_index),UNIQUE(tenant_id,storage_key),FOREIGN KEY(tenant_id,upload_id) REFERENCES uploads(tenant_id,id));
CREATE FUNCTION validate_part() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE u uploads%ROWTYPE; expected bigint; BEGIN SELECT * INTO u FROM uploads WHERE tenant_id=NEW.tenant_id AND id=NEW.upload_id FOR UPDATE; IF NOT FOUND OR u.state<>'open' OR u.expires_at<=now() THEN RAISE EXCEPTION 'upload not writable' USING ERRCODE='55000'; END IF; expected=least(u.chunk_bytes,u.total_bytes-NEW.part_index::bigint*u.chunk_bytes); IF expected<1 OR NEW.size_bytes<>expected THEN RAISE EXCEPTION 'invalid chunk range' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER part_shape BEFORE INSERT ON upload_parts FOR EACH ROW EXECUTE FUNCTION validate_part();
CREATE TABLE metrics(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('metric') STORED,version integer NOT NULL CHECK(version>0),code text NOT NULL,unit text NOT NULL CHECK(length(unit) BETWEEN 1 AND 40),metric_type text NOT NULL CHECK(metric_type IN('ratio','count','decimal')),PRIMARY KEY(tenant_id,id,version),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind));
CREATE TABLE observations(tenant_id uuid NOT NULL,id uuid NOT NULL,study_id uuid NOT NULL,metric_id uuid NOT NULL,metric_version integer NOT NULL,source_event_id text NOT NULL CHECK(length(source_event_id) BETWEEN 1 AND 200),status text NOT NULL CHECK(status IN('observed','missing','suppressed','invalid')),numerator numeric(24,9),denominator numeric(24,9),value numeric(24,9),missing_reason text,observed_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,study_id,source_event_id,metric_id,metric_version),FOREIGN KEY(tenant_id,study_id) REFERENCES studies(tenant_id,id),FOREIGN KEY(tenant_id,metric_id,metric_version) REFERENCES metrics(tenant_id,id,version),CHECK((status='observed' AND value IS NOT NULL AND missing_reason IS NULL) OR (status<>'observed' AND value IS NULL AND missing_reason IS NOT NULL AND length(missing_reason)>0)),CHECK((num_nonnulls(numerator,denominator)=0) OR (num_nonnulls(numerator,denominator)=2 AND numerator>=0 AND denominator>0 AND numerator<=denominator AND abs(value-numerator/denominator)<=0.000000001)));
CREATE TABLE holds(tenant_id uuid NOT NULL,id uuid NOT NULL,scope_id uuid NOT NULL,hold_type text NOT NULL CHECK(hold_type IN('safety','security','rights','retention')),reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 2000),applied_by uuid NOT NULL,applied_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,release_decision_id uuid,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,applied_by) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,release_decision_id) REFERENCES review_decisions(tenant_id,id),CHECK((released_at IS NULL AND release_decision_id IS NULL) OR (released_at>=applied_at AND release_decision_id IS NOT NULL)));
CREATE INDEX holds_active ON holds(tenant_id,scope_id,hold_type) WHERE released_at IS NULL;
CREATE TABLE budgets(tenant_id uuid NOT NULL,id uuid NOT NULL,ceiling_units bigint NOT NULL CHECK(ceiling_units>=0),reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units>=0),actual_units bigint NOT NULL DEFAULT 0 CHECK(actual_units>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE FUNCTION reserve_budget(b uuid,units bigint) RETURNS boolean LANGUAGE plpgsql AS $$BEGIN IF units<=0 THEN RAISE EXCEPTION 'positive units required' USING ERRCODE='23514'; END IF; UPDATE budgets SET reserved_units=reserved_units+units,version=version+1 WHERE tenant_id=current_tenant() AND id=b AND ceiling_units-actual_units-reserved_units>=units; RETURN FOUND; END$$;
CREATE TABLE jobs(tenant_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,type text NOT NULL CHECK(type IN('upload_verify','import_validate','outbox_deliver','cleanup')),state text NOT NULL CHECK(state IN('queued','running','succeeded','failed','cancel_requested','cancelled')),attempt integer NOT NULL DEFAULT 0 CHECK(attempt>=0),available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE INDEX jobs_claim ON jobs(tenant_id,available_at,id) WHERE state IN('queued','running');
CREATE TABLE audit_events(tenant_id uuid NOT NULL,id uuid NOT NULL,actor_id uuid,action text NOT NULL,object_id uuid,object_version bigint CHECK(object_version>0),target_ref_digest text CHECK(target_ref_digest ~ '^[a-f0-9]{64}$'),correlation_id uuid NOT NULL,outcome text NOT NULL CHECK(outcome IN('committed','denied','failed')),occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,object_id) REFERENCES resources(tenant_id,id),CHECK(outcome<>'committed' OR (actor_id IS NOT NULL AND object_id IS NOT NULL AND object_version IS NOT NULL)));
CREATE INDEX audit_object ON audit_events(tenant_id,object_id,occurred_at,id);
CREATE TABLE command_receipts(tenant_id uuid NOT NULL,principal_id uuid NOT NULL,operation text NOT NULL,idempotency_key text NOT NULL CHECK(length(idempotency_key) BETWEEN 16 AND 128),request_sha256 text NOT NULL CHECK(request_sha256 ~ '^[a-f0-9]{64}$'),receipt_id uuid NOT NULL,resource_id uuid NOT NULL,resource_version bigint NOT NULL CHECK(resource_version>0),state text NOT NULL,job_id uuid,correlation_id uuid NOT NULL,committed_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',PRIMARY KEY(tenant_id,principal_id,operation,idempotency_key),UNIQUE(tenant_id,receipt_id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES jobs(tenant_id,id));
CREATE TABLE outbox(tenant_id uuid NOT NULL,event_id uuid NOT NULL,aggregate_id uuid NOT NULL,aggregate_version bigint NOT NULL CHECK(aggregate_version>0),sequence bigint NOT NULL CHECK(sequence>0),event_type text NOT NULL CHECK(length(event_type) BETWEEN 1 AND 100),schema_version integer NOT NULL CHECK(schema_version=1),actor_id uuid NOT NULL,receipt_id uuid,correlation_id uuid NOT NULL,causation_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,event_id),UNIQUE(tenant_id,aggregate_id,sequence),FOREIGN KEY(tenant_id,aggregate_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,receipt_id) REFERENCES command_receipts(tenant_id,receipt_id));
CREATE TABLE outbox_delivery(tenant_id uuid NOT NULL,event_id uuid NOT NULL,consumer_id text NOT NULL,attempt integer NOT NULL DEFAULT 0 CHECK(attempt>=0),next_attempt_at timestamptz NOT NULL DEFAULT now(),state text NOT NULL CHECK(state IN('pending','transmitted','acknowledged','processed','dead_letter')),PRIMARY KEY(tenant_id,event_id,consumer_id),FOREIGN KEY(tenant_id,event_id) REFERENCES outbox(tenant_id,event_id));
CREATE TABLE inbox(tenant_id uuid NOT NULL,consumer_id text NOT NULL,event_id uuid NOT NULL,sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,consumer_id,event_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE support_access(tenant_id uuid NOT NULL,id uuid NOT NULL,case_id uuid NOT NULL,principal_id uuid NOT NULL,scope_id uuid NOT NULL,decision_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,case_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,decision_id) REFERENCES review_decisions(tenant_id,id));
CREATE TABLE restriction_ledger(tenant_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,type text NOT NULL CHECK(type IN('revocation','deletion','hold','release')),effective_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),proof_sha256 text NOT NULL CHECK(proof_sha256 ~ '^[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));

CREATE TABLE institution_applications(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('institution') STORED,legal_name text NOT NULL CHECK(length(legal_name) BETWEEN 1 AND 200),registration_jurisdiction text NOT NULL CHECK(length(registration_jurisdiction) BETWEEN 1 AND 200),registration_reference text NOT NULL CHECK(length(registration_reference) BETWEEN 1 AND 200),entity_type text NOT NULL CHECK(length(entity_type) BETWEEN 1 AND 200),representative_id uuid NOT NULL,contact_email text NOT NULL CHECK(length(contact_email) BETWEEN 3 AND 254),terms_version text NOT NULL CHECK(length(terms_version) BETWEEN 1 AND 200),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,representative_id) REFERENCES principals(tenant_id,id));
CREATE TABLE application_evidence(tenant_id uuid NOT NULL,application_id uuid NOT NULL,artifact_id uuid NOT NULL,PRIMARY KEY(tenant_id,application_id,artifact_id),FOREIGN KEY(tenant_id,application_id) REFERENCES institution_applications(tenant_id,id),FOREIGN KEY(tenant_id,artifact_id) REFERENCES artifacts(tenant_id,id));
CREATE TABLE membership_invitations(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('membership_invitation') STORED,email text NOT NULL CHECK(length(email) BETWEEN 3 AND 254),expires_at timestamptz NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,created_by) REFERENCES principals(tenant_id,id),CHECK(expires_at>created_at));
CREATE TABLE invitation_roles(tenant_id uuid NOT NULL,invitation_id uuid NOT NULL,role_code text NOT NULL REFERENCES role_codes(code),PRIMARY KEY(tenant_id,invitation_id,role_code),FOREIGN KEY(tenant_id,invitation_id) REFERENCES membership_invitations(tenant_id,id));
CREATE TABLE invitation_scopes(tenant_id uuid NOT NULL,invitation_id uuid NOT NULL,scope_id uuid NOT NULL,PRIMARY KEY(tenant_id,invitation_id,scope_id),FOREIGN KEY(tenant_id,invitation_id) REFERENCES membership_invitations(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES resources(tenant_id,id));
CREATE TABLE access_requests(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('access_request') STORED,release_id uuid NOT NULL,study_id uuid,external_study_ref uuid,external_kind text GENERATED ALWAYS AS ('study') STORED,purpose text NOT NULL CHECK(length(purpose) BETWEEN 1 AND 200),cohort_sha256 text NOT NULL CHECK(cohort_sha256 ~ '^[a-f0-9]{64}$'),region text NOT NULL CHECK(length(region) BETWEEN 1 AND 80),valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,release_id) REFERENCES dataset_releases(tenant_id,id),FOREIGN KEY(tenant_id,study_id) REFERENCES studies(tenant_id,id),FOREIGN KEY(tenant_id,external_study_ref,external_kind) REFERENCES external_references(tenant_id,id,remote_kind),CHECK(num_nonnulls(study_id,external_study_ref)=1),CHECK(valid_from<valid_until));
CREATE TABLE request_fields(tenant_id uuid NOT NULL,request_id uuid NOT NULL,field_code text NOT NULL CHECK(field_code ~ '^[a-z][a-z0-9_]{0,79}$'),PRIMARY KEY(tenant_id,request_id,field_code),FOREIGN KEY(tenant_id,request_id) REFERENCES access_requests(tenant_id,id));
CREATE TABLE request_subjects(tenant_id uuid NOT NULL,request_id uuid NOT NULL,principal_id uuid NOT NULL,PRIMARY KEY(tenant_id,request_id,principal_id),FOREIGN KEY(tenant_id,request_id) REFERENCES access_requests(tenant_id,id),FOREIGN KEY(tenant_id,principal_id) REFERENCES principals(tenant_id,id));
CREATE TABLE import_manifests(tenant_id uuid NOT NULL,import_id uuid NOT NULL,source_id uuid NOT NULL,source_kind text GENERATED ALWAYS AS ('data_source') STORED,schema_id uuid NOT NULL,schema_kind text GENERATED ALWAYS AS ('schema') STORED,mapping_id uuid NOT NULL,mapping_kind text GENERATED ALWAYS AS ('mapping') STORED,PRIMARY KEY(tenant_id,import_id),FOREIGN KEY(tenant_id,import_id) REFERENCES imports(tenant_id,id),FOREIGN KEY(tenant_id,source_id,source_kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,schema_id,schema_kind) REFERENCES resources(tenant_id,id,kind),FOREIGN KEY(tenant_id,mapping_id,mapping_kind) REFERENCES resources(tenant_id,id,kind));
CREATE TABLE import_files(tenant_id uuid NOT NULL,import_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),size_bytes bigint NOT NULL CHECK(size_bytes>=0),sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,import_id,name),FOREIGN KEY(tenant_id,import_id) REFERENCES import_manifests(tenant_id,import_id));
CREATE TABLE study_sites(tenant_id uuid NOT NULL,study_id uuid NOT NULL,site_id uuid NOT NULL,site_kind text GENERATED ALWAYS AS ('site') STORED,PRIMARY KEY(tenant_id,study_id,site_id),FOREIGN KEY(tenant_id,study_id) REFERENCES studies(tenant_id,id),FOREIGN KEY(tenant_id,site_id,site_kind) REFERENCES resources(tenant_id,id,kind));
ALTER TABLE studies ADD COLUMN protocol_id uuid,ADD COLUMN protocol_kind text GENERATED ALWAYS AS ('protocol') STORED,ADD COLUMN configuration_id uuid,ADD COLUMN configuration_kind text GENERATED ALWAYS AS ('configuration') STORED,ADD FOREIGN KEY(tenant_id,protocol_id,protocol_kind) REFERENCES resources(tenant_id,id,kind),ADD FOREIGN KEY(tenant_id,configuration_id,configuration_kind) REFERENCES resources(tenant_id,id,kind);
CREATE TABLE safety_concerns(tenant_id uuid NOT NULL,id uuid NOT NULL,kind text GENERATED ALWAYS AS ('safety_concern') STORED,concern text NOT NULL CHECK(length(concern) BETWEEN 1 AND 20000),contact text CHECK(length(contact)<=200),occurred_at timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id,kind) REFERENCES resources(tenant_id,id,kind));
CREATE TABLE concern_scopes(tenant_id uuid NOT NULL,concern_id uuid NOT NULL,scope_id uuid NOT NULL,PRIMARY KEY(tenant_id,concern_id,scope_id),FOREIGN KEY(tenant_id,concern_id) REFERENCES safety_concerns(tenant_id,id),FOREIGN KEY(tenant_id,scope_id) REFERENCES resources(tenant_id,id));
ALTER TABLE outbox ADD COLUMN result_state text CHECK(result_state IN('stored','quarantined','integrity_failed','aborted','expired')),ADD COLUMN artifact_ref uuid,ADD COLUMN part_index integer CHECK(part_index BETWEEN 0 AND 1279),ADD FOREIGN KEY(tenant_id,artifact_ref) REFERENCES artifacts(tenant_id,id),ADD CHECK((receipt_id IS NOT NULL AND result_state IS NULL AND artifact_ref IS NULL AND part_index IS NULL) OR (receipt_id IS NULL AND result_state IS NOT NULL));

ALTER TABLE outbox ADD CHECK(receipt_id IS NOT NULL OR (event_type='UploadPartStored' AND result_state='stored' AND part_index IS NOT NULL AND artifact_ref IS NULL) OR (event_type='UploadVerificationCompleted' AND part_index IS NULL AND ((result_state='quarantined' AND artifact_ref IS NOT NULL) OR (result_state='integrity_failed' AND artifact_ref IS NULL))) OR (event_type='UploadAborted' AND result_state='aborted' AND part_index IS NULL AND artifact_ref IS NULL) OR (event_type='SupportAccessExpired' AND result_state='expired' AND part_index IS NULL AND artifact_ref IS NULL));
RESET ROLE;
